import java.util.*;

class Solution {
  private int[] parent;

  private int find(int x) {
    while (parent[x] != x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }

  public int[] minimumCost(int n, int[][] edges, int[][] query) {
    parent = new int[n];
    Arrays.fill(parent, -1);
    for (int i = 0; i < n; i++) parent[i] = i;
    for (int[] edge : edges) {
      int a = find(edge[0]), b = find(edge[1]);
      if (a != b) parent[a] = b;
    }
    int[] value = new int[n];
    Arrays.fill(value, -1);
    for (int[] edge : edges) {
      int root = find(edge[0]);
      value[root] &= edge[2];
    }
    int[] answer = new int[query.length];
    for (int i = 0; i < query.length; i++) {
      int a = find(query[i][0]), b = find(query[i][1]);
      answer[i] = a == b ? value[a] : -1;
    }
    return answer;
  }
}
